const response = $input.first().json;
if (!Array.isArray(response.ideas) || response.ideas.length !== 5) throw new Error('AI must return exactly five ideas');
return response.ideas.map((idea, index) => ({ json: { ...idea, _slotIndex: index } }));

const created = $input.all().map(item => {
  const response = item.json;
  const payload = response.data ?? response;
  const idea = typeof payload === 'string' ? JSON.parse(payload) : payload;

  return idea;
});

if (
  created.length !== 5 ||
  created.some(idea => !idea || typeof idea.id !== 'string' || idea.id.length === 0)
) {
  throw new Error(
    `Symfony must return five created ideas with IDs. Received: ${created.length}`
  );
}

const now = new Date();
const daysSinceMonday = (now.getDay() + 6) % 7;
now.setDate(now.getDate() - daysSinceMonday);

const weekStart = now.toISOString().slice(0, 10);
const minutes = [30, 30, 40, 40, 30];

const slots = created.map((idea, index) => ({
  ideaId: idea.id,
  type: index < 3 ? 'priority' : 'reserve',
  assignee: index < 2 ? 'A' : 'B',
  estimatedMinutes: minutes[index]
}));

return [{
  json: {
    weekStart,
    capacityPersonA: 90,
    capacityPersonB: 150,
    slots,
    generatedIdeaCount: created.length,
    note: 'Synthetic AI suggestions; human selection and review are still required.'
  }
}];

const plan = $input.first().json;
const slots = plan.slots || [];
const lines = [
  'Weekly content plan — week of ' + plan.weekStart,
  'Priorities: ' + slots.filter(slot => slot.type === 'priority').length + ' | Reserves: ' + slots.filter(slot => slot.type === 'reserve').length,
  'Person A: ' + plan.allocatedMinutes.A + '/' + plan.capacity.A + ' minutes',
  'Person B: ' + plan.allocatedMinutes.B + '/' + plan.capacity.B + ' minutes',
  '',
  ...slots.map((slot, index) => (index + 1) + '. [' + slot.type + '] ' + slot.title + ' — Person ' + slot.assignee + ', ' + slot.estimatedMinutes + ' min'),
  '',
  'All AI suggestions remain drafts. A human must review and approve each exact content version before handoff.'
];
const overview = lines.join('\n');
return [{ json: { weeklyPlan: plan, weeklyOverview: overview, emailDraft: { delivery: 'not_sent', to: 'reviewer@example.invalid', subject: 'Bro World AI weekly content plan — ' + plan.weekStart, body: overview, requiresHumanReview: true } } }];
